const JSON_ATTRIBUTE_TYPES = new Set(['json', 'blocks']);

/**
 * Re-serializes JSON/blocks columns in a row before INSERT.
 *
 * mysql2 and node-pg parse JSON/JSONB columns on SELECT into JS objects; knex
 * does not re-serialize those objects on INSERT. Stringify object/array values
 * for json and blocks attributes. Values that are already strings (typical of
 * SQLite) are left unchanged.
 */
export const serializeJsonColumns = (
  row: Record<string, any>,
  meta: { attributes?: Record<string, any> } | null | undefined
): Record<string, any> => {
  if (!meta?.attributes) {
    return row;
  }

  for (const attribute of Object.values(meta.attributes) as any[]) {
    if (!JSON_ATTRIBUTE_TYPES.has(attribute.type)) {
      continue;
    }

    const columnName = attribute.columnName;
    if (!columnName || !(columnName in row)) {
      continue;
    }

    const value = row[columnName];
    if (value != null && typeof value === 'object') {
      row[columnName] = JSON.stringify(value);
    }
  }

  return row;
};

import { contentTypes as contentTypesUtils, async } from '@strapi/utils';
import type { Schema } from '@strapi/types';

import { getBatchToDiscard } from './database/5.0.0-discard-drafts';

export interface Input {
  oldContentTypes: Record<string, Schema.ContentType>;
  contentTypes: Record<string, Schema.ContentType>;
}

/**
 * Enable draft and publish for content types.
 *
 * Draft and publish disabled content types will have their entries published,
 * this migration clones those entries as drafts.
 *
 * TODO: Clone components, dynamic zones and relations
 */
const enableDraftAndPublish = async ({ oldContentTypes, contentTypes }: Input) => {
  if (!oldContentTypes) {
    return;
  }

  // run the after content types migrations
  return strapi.db.transaction(async (trx) => {
    for (const uid in contentTypes) {
      if (!oldContentTypes[uid]) {
        continue;
      }

      const oldContentType = oldContentTypes[uid];
      const contentType = contentTypes[uid];

      // if d&p was enabled set publishedAt to eq createdAt
      if (
        !contentTypesUtils.hasDraftAndPublish(oldContentType) &&
        contentTypesUtils.hasDraftAndPublish(contentType)
      ) {
        const discardDraft = async (entry: { documentId: string; locale: string }) =>
          strapi
            .documents(uid as any)
            // Discard draft by referencing the documentId and locale
            .discardDraft({ documentId: entry.documentId, locale: entry.locale });

        /**
         * Load a batch of entries (batched to prevent loading millions of rows at once ),
         * and discard them using the document service.
         */
        for await (const batch of getBatchToDiscard({ db: strapi.db, trx, uid })) {
          await async.map(batch, discardDraft, { concurrency: 10 });
        }
      }
    }
  });
};

const disableDraftAndPublish = async ({ oldContentTypes, contentTypes }: Input) => {
  if (!oldContentTypes) {
    return;
  }

  for (const uid in contentTypes) {
    if (!oldContentTypes[uid]) {
      continue;
    }

    const oldContentType = oldContentTypes[uid];
    const contentType = contentTypes[uid];

    // if d&p was disabled remove unpublish content before sync
    if (
      contentTypesUtils.hasDraftAndPublish(oldContentType) &&
      !contentTypesUtils.hasDraftAndPublish(contentType)
    ) {
      await strapi.db?.queryBuilder(uid).delete().where({ published_at: null }).execute();
    }
  }
};

export { enableDraftAndPublish as enable, disableDraftAndPublish as disable };

import { contentTypes as contentTypesUtils } from '@strapi/utils';
import _ from 'lodash';
import { Input } from './draft-publish';

interface ContentTypeData {
  id: number;
  documentId: string;
  publishedAt: Date;
  firstPublishedAt: Date;
  locale: string;
}

const enableFirstPublishedAt = async ({ oldContentTypes, contentTypes }: Input) => {
  if (!oldContentTypes) {
    return;
  }

  return strapi.db.transaction(async (trx) => {
    for (const uid in contentTypes) {
      if (!oldContentTypes[uid]) {
        continue;
      }

      const contentType = contentTypes[uid];

      if (!contentTypesUtils.hasFirstPublishedAtField(contentType)) {
        continue;
      }

      if (!contentType.attributes?.firstPublishedAt) {
        continue;
      }

      const content: ContentTypeData[] = await strapi.db
        .queryBuilder(uid)
        .select('*')
        .transacting(trx)
        .execute();

      // Process content types in pairs: draft and published.
      // If only one exist, which means the value is not published yet and we can ignore it
      const groupedContent = _.groupBy(content, (item) => `${item.documentId}-${item.locale}`);

      for (const items of Object.values(groupedContent)) {
        // If there is only one item, which means nothing is published yet for this locale
        if (items.length <= 1) {
          continue;
        }

        // If firstPublishedAt is already present, do not do anything
        if (items[0].firstPublishedAt != null && items[1].firstPublishedAt != null) {
          continue;
        }

        const publishedContent = items.filter((item) => item.publishedAt != null).at(0);
        if (!publishedContent) {
          continue;
        }

        await strapi.db
          .queryBuilder(uid)
          .update({
            firstPublishedAt: new Date(publishedContent.publishedAt),
          })
          .where({
            documentId: publishedContent.documentId,
            locale: publishedContent.locale,
          })
          .transacting(trx)
          .execute();
      }
    }
  });
};

export { enableFirstPublishedAt as enable };

import { Input } from './draft-publish';

// if i18N enabled set default locale
const enableI18n = async ({ oldContentTypes, contentTypes }: Input) => {
  const { isLocalizedContentType } = strapi.plugin('i18n')?.service('content-types') ?? {};
  const { getDefaultLocale } = strapi.plugin('i18n')?.service('locales') ?? {};

  if (!oldContentTypes) {
    return;
  }

  for (const uid in contentTypes) {
    if (!oldContentTypes[uid]) {
      continue;
    }

    const oldContentType = oldContentTypes[uid];
    const contentType = contentTypes[uid];

    if (!isLocalizedContentType(oldContentType) && isLocalizedContentType(contentType)) {
      const defaultLocale = await getDefaultLocale();

      await strapi.db.query(uid).updateMany({
        where: { locale: null },
        data: { locale: defaultLocale },
      });
    }
  }
};

const disableI18n = async ({ oldContentTypes, contentTypes }: Input) => {
  const { isLocalizedContentType } = strapi.plugin('i18n')?.service('content-types') ?? {};
  const { getDefaultLocale } = strapi.plugin('i18n')?.service('locales') ?? {};

  if (!oldContentTypes) {
    return;
  }

  for (const uid in contentTypes) {
    if (!oldContentTypes[uid]) {
      continue;
    }

    const oldContentType = oldContentTypes[uid];
    const contentType = contentTypes[uid];

    // if i18N is disabled remove non default locales before sync
    if (isLocalizedContentType(oldContentType) && !isLocalizedContentType(contentType)) {
      const defaultLocale = await getDefaultLocale();

      await Promise.all([
        // Delete all entities that are not in the default locale
        strapi.db.query(uid).deleteMany({
          where: { locale: { $ne: defaultLocale } },
        }),
        // Set locale to null for the rest
        strapi.db.query(uid).updateMany({
          where: { locale: { $eq: defaultLocale } },
          data: { locale: null },
        }),
      ]);
    }
  }
};

export { enableI18n as enable, disableI18n as disable };

import type { Knex } from 'knex';

import type { Database } from '..';

export interface UserMigrationProvider {
  shouldRun(): Promise<boolean>;
  up(): Promise<void>;
  down(): Promise<void>;
}

export interface InternalMigrationProvider {
  register(migration: Migration): void;
  shouldRun(): Promise<boolean>;
  up(): Promise<void>;
  down(): Promise<void>;
}
export interface MigrationProvider {
  providers: { internal: InternalMigrationProvider };
  shouldRun(): Promise<boolean>;
  up(): Promise<void>;
  down(): Promise<void>;
}

export type Context = { db: Database };

export type MigrationResolverParams = {
  name: string;
  path?: string;
  context: Context;
};

export type MigrationRunnerFn = () => Promise<void> | Promise<Promise<void>>;

export type MigrationResolver = (params: MigrationResolverParams) => {
  name: string;
  path?: string;
  up: MigrationRunnerFn;
  down: MigrationRunnerFn;
};

export type MigrationFn = (knex: Knex.Transaction, db: Database) => Promise<void>;

export type Migration = {
  name: string;
  up: MigrationFn;
  down: MigrationFn;
};

export const wrapTransaction = (db: Database) => (fn: MigrationFn) => () => {
  return db.transaction(({ trx }) => Promise.resolve(fn(trx, db)));
};

import path from 'path';

import fse from 'fs-extra';

/**
 * Discover user migration files in a directory.
 * Matches umzug's non-recursive `*.{js,sql}` glob (fast-glob defaults:
 * `dot: false`, `onlyFiles: true`, `followSymbolicLinks: true`) with
 * alphabetical ordering.
 */
export const discoverMigrationFiles = (dir: string): string[] => {
  if (!fse.existsSync(dir)) {
    return [];
  }

  return fse
    .readdirSync(dir, { withFileTypes: true })
    .filter((entry) => {
      if (entry.name.startsWith('.')) {
        return false;
      }

      if (!entry.name.endsWith('.js') && !entry.name.endsWith('.sql')) {
        return false;
      }

      // Regular files: accept without stat so a TOCTOU race (file removed
      // between readdir and stat) surfaces later instead of being swallowed.
      if (entry.isFile()) {
        return true;
      }

      // Dirent#isFile() is false for symlinks; only then follow the target
      // (umzug/fast-glob followSymbolicLinks: include symlink→file, skip
      // symlink→directory and broken links).
      if (entry.isSymbolicLink()) {
        try {
          return fse.statSync(path.join(dir, entry.name)).isFile();
        } catch {
          return false;
        }
      }

      return false;
    })
    .map((entry) => path.resolve(dir, entry.name))
    .sort();
};

export interface HeartbeatLoggerOptions {
  /** Minimum time between heartbeat log lines. Defaults to 60s. */
  intervalMs?: number;
  /** Injectable clock for tests. */
  now?: () => number;
}

export interface HeartbeatLogger {
  /**
   * Emit `buildMessage(elapsedSeconds)` at most once per interval.
   * Safe to call on every batch — no-ops until the interval elapses.
   */
  tick(buildMessage: (elapsedSeconds: number) => string): void;
}

/**
 * Append-only, time-throttled progress logger for long-running migrations.
 * Never rewrites terminal lines — one complete Winston info line per tick.
 */
export const createHeartbeatLogger = (
  log: (message: string) => void,
  { intervalMs = 60_000, now = () => Date.now() }: HeartbeatLoggerOptions = {}
): HeartbeatLogger => {
  const startedAt = now();
  let lastEmittedAt = startedAt;

  return {
    tick(buildMessage) {
      const current = now();
      if (current - lastEmittedAt < intervalMs) {
        return;
      }

      const elapsedSeconds = Math.floor((current - startedAt) / 1000);
      log(buildMessage(elapsedSeconds));
      lastEmittedAt = current;
    },
  };
};

import type { Knex } from 'knex';
import createDebug from 'debug';
import type { Migration } from '../common';
import type { Metadata } from '../../metadata';
import { type Database } from '../..';
import { identifiers } from '../../utils/identifiers';

const debug = createDebug('strapi::database::migration');

type NameDiff<T> = {
  short: T;
  full: T;
};

type IndexDiff = NameDiff<{ index: number; key: string; tableName: string; indexName: string }>;

// key isn't really used except for debugging, but it's helpful to track down problems
type IdentifierDiffs = {
  indexes: IndexDiff[];
  tables: NameDiff<{ index: number; key: string; tableName: string }>[];
  columns: NameDiff<{ index: number; key: string; tableName: string; columnName: string }>[];
};

export const renameIdentifiersLongerThanMaxLength: Migration = {
  name: '5.0.0-rename-identifiers-longer-than-max-length',
  async up(knex, db) {
    const md = db.metadata;

    const diffs = findDiffs(md);
    // migrate indexes before tables so we know to target the original tableName
    for (const indexDiff of diffs.indexes) {
      await renameIndex(knex, db, indexDiff);
    }

    // migrate columns before table names so we know to target the original tableName
    for (const columnDiff of diffs.columns) {
      const { full, short } = columnDiff;
      const tableName = full.tableName;

      const hasTable = await knex.schema.hasTable(tableName);

      if (hasTable) {
        // tablebuilder methods MUST be synchronous and so you cannot use async inside it, which is why we check the column here
        const hasColumn = await knex.schema.hasColumn(tableName, full.columnName);

        if (hasColumn) {
          await knex.schema.alterTable(tableName, async (table) => {
            debug(`renaming column ${full.columnName} to ${short.columnName}`);
            table.renameColumn(full.columnName, short.columnName);
          });
        }
      }
    }

    // migrate table names
    for (const tableDiff of diffs.tables) {
      const hasTable = await knex.schema.hasTable(tableDiff.full.tableName);

      if (hasTable) {
        debug(`renaming table ${tableDiff.full.tableName} to ${tableDiff.short.tableName}`);
        await knex.schema.renameTable(tableDiff.full.tableName, tableDiff.short.tableName);
      }
    }
  },
  async down() {
    throw new Error('not implemented');
  },
};

const renameIndex = async (knex: Knex, db: Database, diff: IndexDiff) => {
  const client = db.config.connection.client;
  const short = diff.short;
  const full = diff.full;

  if (full.indexName === short.indexName) {
    debug(`not renaming index ${full.indexName} because name hasn't changed`);
    return;
  }

  // fk indexes can't be easily renamed, and will be recreated by db sync
  // if this misses something due to the loose string matching, it's not critical, it just means index will be rebuilt in db sync
  if (short.indexName.endsWith('fk') || full.indexName.endsWith('fk')) {
    return;
  }

  debug(`renaming index from ${full.indexName} to ${short.indexName}`);

  // If schema creation has never actually run before, none of these will exist, and they will throw an error
  // we have no way of running an "if exists" other than a per-dialect manual check, which we won't do
  // because even if it fails for some other reason, the schema sync will recreate them anyway
  // Therefore, we wrap this in a nested transaction (considering we are running this migration in a transaction)
  // so that we can suppress the error
  try {
    await knex.transaction(async (trx) => {
      if (client === 'mysql' || client === 'mariadb') {
        await knex
          .raw('ALTER TABLE ?? RENAME INDEX ?? TO ??', [
            full.tableName,
            full.indexName,
            short.indexName,
          ])
          .transacting(trx);
      } else if (client === 'pg' || client === 'postgres') {
        await knex
          .raw('ALTER INDEX ?? RENAME TO ??', [full.indexName, short.indexName])
          .transacting(trx);
      } else if (['sqlite', 'sqlite3', 'better-sqlite3'].includes(client as any)) {
        // SQLite doesn't support renaming, so rather than trying to drop/recreate we'll let db sync handle it
        debug(`SQLite does not support index renaming, not renaming index ${full.indexName}`);
      } else {
        debug(`No db client name matches, not renaming index ${full.indexName}`);
      }
    });
  } catch (err) {
    debug(`error creating index: ${JSON.stringify(err)}`);
  }
};

const findDiffs = (shortMap: Metadata) => {
  const diffs = {
    tables: [],
    columns: [],
    indexes: [],
  } as IdentifierDiffs;

  const shortArr = Array.from(shortMap.entries());

  shortArr.forEach(([, shortObj], index) => {
    const fullTableName = identifiers.getUnshortenedName(shortObj.tableName);
    if (!fullTableName) {
      throw new Error(`Missing full table name for ${shortObj.tableName}`);
    }

    // find table name diffs
    if (shortObj.tableName !== fullTableName) {
      diffs.tables.push({
        full: {
          index,
          key: 'tableName',
          tableName: fullTableName,
        },
        short: {
          index,
          key: 'tableName',
          tableName: shortObj.tableName,
        },
      });
    }

    // find column name diffs
    // eslint-disable-next-line guard-for-in
    for (const attrKey in shortObj.attributes) {
      if (shortObj.attributes[attrKey].type === 'relation') {
        continue;
      }

      // TODO: add more type checks so we don't need any
      const attr = shortObj.attributes[attrKey] as any;
      const shortColumnName = attr.columnName;
      const longColumnName = identifiers.getUnshortenedName(shortColumnName);

      if (!shortColumnName || !longColumnName) {
        throw new Error(`missing column name(s) for attribute ${JSON.stringify(attr, null, 2)}`);
      }
      if (shortColumnName && longColumnName && shortColumnName !== longColumnName) {
        diffs.columns.push({
          short: {
            index,
            tableName: fullTableName, // NOTE: this means that we must rename columns before tables
            key: `attributes.${attrKey}`,
            columnName: shortColumnName,
          },
          full: {
            index,
            tableName: fullTableName,
            key: `attributes.${attrKey}`,
            columnName: longColumnName,
          },
        });
      }
    }

    // find index name diffs
    // eslint-disable-next-line guard-for-in
    for (const attrKey in shortObj.indexes) {
      const shortIndexName = shortObj.indexes[attrKey].name;
      const longIndexName = identifiers.getUnshortenedName(shortIndexName);
      if (!longIndexName) {
        throw new Error(`Missing full index name for ${shortIndexName}`);
      }

      if (shortIndexName && longIndexName && shortIndexName !== longIndexName) {
        diffs.indexes.push({
          short: {
            index,
            tableName: fullTableName, // NOTE: this means that we must rename columns before tables
            key: `indexes.${attrKey}`,
            indexName: shortIndexName,
          },
          full: {
            index,
            tableName: fullTableName,
            key: `indexes.${attrKey}`,
            indexName: longIndexName,
          },
        });
      }
    }
  });

  return diffs;
};

/**
 * NOTE: This migration avoids using the `identifiers` utility.
 * As the `5.0.0-01-convert-identifiers-long-than-max-length`
 * migration does not convert the `localizations` join tables, as they are not
 * tables that exist anymore in v5 and are not in the db metadata.
 *
 * This migration therefore relies on the fact that those tables still exist, and
 * references them directly.
 *
 * Database join table name: `categories_localizations_links`
 * Actual `identifiers` returned join table name: `categories_localizations_lnk`
 *
 */
import { createId } from '@paralleldrive/cuid2';
import { snakeCase } from 'lodash/fp';
import type { Knex } from 'knex';

import type { Migration } from '../common';
import { createHeartbeatLogger, type HeartbeatLogger } from '../heartbeat';
import type { Database } from '../..';
import type { Meta } from '../../metadata';

function getBatchSize(trx: Knex, defaultSize: number = 1000): number {
  const client = trx.client.config.client;
  const isSQLite =
    typeof client === 'string' && ['sqlite', 'sqlite3', 'better-sqlite3'].includes(client);
  return isSQLite ? Math.min(defaultSize, 250) : defaultSize;
}

interface Params {
  joinColumn: string;
  inverseJoinColumn: string;
  tableName: string;
  joinTableName: string;
}

const QUERIES = {
  async postgres(knex: Knex, params: Params) {
    const res = await knex.raw(
      `
    SELECT :tableName:.id as id, string_agg(DISTINCT :inverseJoinColumn:::character varying, ',') as other_ids
    FROM :tableName:
    LEFT JOIN :joinTableName: ON :tableName:.id = :joinTableName:.:joinColumn:
    WHERE :tableName:.document_id IS NULL
    GROUP BY :tableName:.id, :joinTableName:.:joinColumn:
    LIMIT 1;
  `,
      params
    );

    return res.rows;
  },
  async mysql(knex: Knex, params: Params) {
    const [res] = await knex.raw(
      `
    SELECT :tableName:.id as id, group_concat(DISTINCT :inverseJoinColumn:) as other_ids
    FROM :tableName:
    LEFT JOIN :joinTableName: ON :tableName:.id = :joinTableName:.:joinColumn:
    WHERE :tableName:.document_id IS NULL
    GROUP BY :tableName:.id, :joinTableName:.:joinColumn:
    LIMIT 1;
  `,
      params
    );

    return res;
  },
  async sqlite(knex: Knex, params: Params) {
    return knex.raw(
      `
    SELECT :tableName:.id as id, group_concat(DISTINCT :inverseJoinColumn:) as other_ids
    FROM :tableName:
    LEFT JOIN :joinTableName: ON :tableName:.id = :joinTableName:.:joinColumn:
    WHERE :tableName:.document_id IS NULL
    GROUP BY :joinTableName:.:joinColumn:
    LIMIT 1;
    `,
      params
    );
  },
};

const getNextIdsToCreateDocumentId = async (
  db: Database,
  knex: Knex,
  {
    joinColumn,
    inverseJoinColumn,
    tableName,
    joinTableName,
  }: {
    joinColumn: string;
    inverseJoinColumn: string;
    tableName: string;
    joinTableName: string;
  }
): Promise<number[]> => {
  const res = await QUERIES[db.dialect.client as keyof typeof QUERIES](knex, {
    joinColumn,
    inverseJoinColumn,
    tableName,
    joinTableName,
  });

  if (res.length > 0) {
    const row = res[0];
    const otherIds = row.other_ids
      ? row.other_ids.split(',').map((v: string) => parseInt(v, 10))
      : [];

    return [row.id, ...otherIds];
  }

  return [];
};

// Migrate document ids for tables that have localizations
const migrateDocumentIdsWithLocalizations = async (
  db: Database,
  knex: Knex,
  meta: Meta,
  heartbeat: HeartbeatLogger
) => {
  const singularName = meta.singularName.toLowerCase();
  const joinColumn = snakeCase(`${singularName}_id`);
  const inverseJoinColumn = snakeCase(`inv_${singularName}_id`);
  let ids: number[];
  let processed = 0;

  do {
    ids = await getNextIdsToCreateDocumentId(db, knex, {
      joinColumn,
      inverseJoinColumn,
      tableName: meta.tableName,
      joinTableName: snakeCase(`${meta.tableName}_localizations_links`),
    });

    if (ids.length > 0) {
      await knex(meta.tableName).update({ document_id: createId() }).whereIn('id', ids);
      processed += ids.length;
      const rowsProcessed = processed;
      heartbeat.tick(
        (elapsedSeconds) =>
          `[document-id] still running (${elapsedSeconds}s) · ${meta.tableName} ${rowsProcessed} rows processed`
      );
    }
  } while (ids.length > 0);
};

// Migrate document ids for tables that don't have localizations
const migrationDocumentIds = async (
  db: Database,
  knex: Knex,
  meta: Meta,
  heartbeat: HeartbeatLogger
) => {
  const batchSize = getBatchSize(knex);
  const total = +(await knex(meta.tableName).count('* as recordsLeft').whereNull('document_id'))[0]
    .recordsLeft;
  let recordsLeft = total;
  while (recordsLeft > 0) {
    const currentBatchSize = recordsLeft < batchSize ? recordsLeft : batchSize;
    const updateRecords = (
      await knex(meta.tableName).select('id').whereNull('document_id').limit(currentBatchSize)
    ).map((item) => ({ id: item.id, document_id: createId() }));
    await knex(meta.tableName).insert(updateRecords).onConflict('id').merge();
    recordsLeft -= updateRecords.length;
    const processed = total - recordsLeft;
    heartbeat.tick(
      (elapsedSeconds) =>
        `[document-id] still running (${elapsedSeconds}s) · ${meta.tableName} ${processed}/${total}`
    );
  }
};

const isDuplicateColumnError = (error: unknown): boolean => {
  if (!error || typeof error !== 'object') return false;
  const e = error as { code?: string; errno?: number; message?: string };
  if (e.code === '42701') return true;
  if (e.errno === 1060) return true;
  if (typeof e.message === 'string' && /duplicate column/i.test(e.message)) return true;
  return false;
};

const createDocumentIdColumn = async (knex: Knex, tableName: string) => {
  try {
    await knex.schema.alterTable(tableName, (table) => {
      table.string('document_id');
    });
  } catch (error) {
    if (!isDuplicateColumnError(error)) {
      throw error;
    }
  }
};

const hasLocalizationsJoinTable = async (knex: Knex, tableName: string) => {
  const joinTableName = snakeCase(`${tableName}_localizations_links`);
  return knex.schema.hasTable(joinTableName);
};

export const createdDocumentId: Migration = {
  name: '5.0.0-02-created-document-id',
  async up(knex, db) {
    const heartbeat = createHeartbeatLogger((message) => {
      db.logger.info(message);
    });

    for (const meta of db.metadata.values()) {
      const hasTable = await knex.schema.hasTable(meta.tableName);

      if (!hasTable) {
        continue;
      }

      if ('documentId' in meta.attributes) {
        const hasDocumentIdColumn = await knex.schema.hasColumn(meta.tableName, 'document_id');

        if (!hasDocumentIdColumn) {
          await createDocumentIdColumn(knex, meta.tableName);
        }

        if (await hasLocalizationsJoinTable(knex, meta.tableName)) {
          await migrateDocumentIdsWithLocalizations(db, knex, meta, heartbeat);
        } else {
          await migrationDocumentIds(db, knex, meta, heartbeat);
        }
      }
    }
  },
  async down() {
    throw new Error('not implemented');
  },
};

