import { wrapTransaction } from './common';
import { createMigrationRunner } from './runner';
import { internalMigrations } from './internal-migrations';
import { createStorage } from './storage';
import { transformLogMessage } from './logger';

import type { InternalMigrationProvider, Migration } from './common';
import type { Database } from '..';

export const createInternalMigrationProvider = (db: Database): InternalMigrationProvider => {
  const context = { db };
  const migrations: Migration[] = [...internalMigrations];

  const runner = createMigrationRunner({
    storage: createStorage({ db, tableName: 'strapi_migrations_internal' }),
    logger: {
      info(message) {
        db.logger.info(transformLogMessage('info', message));
      },
    },
    getMigrations: async () =>
      migrations.map((migration) => ({
        name: migration.name,
        up: wrapTransaction(context.db)(migration.up),
        down: wrapTransaction(context.db)(migration.down),
      })),
  });

  return {
    async register(migration: Migration) {
      migrations.push(migration);
    },
    async shouldRun() {
      const pendingMigrations = await runner.pending();
      return pendingMigrations.length > 0;
    },
    async up() {
      await runner.up();
    },
    async down() {
      await runner.down();
    },
  };
};

type MigrationLogEvent = {
  event: unknown;
  name: unknown;
  durationSeconds?: unknown;
};

export const transformLogMessage = (level: string, message: unknown) => {
  if (typeof message === 'string') {
    return { level, message };
  }

  if (typeof message === 'object' && message !== null) {
    if ('event' in message && 'name' in message) {
      const { event, name, durationSeconds } = message as MigrationLogEvent;
      let text = `[internal migration]: ${event} ${name}`;

      if (typeof durationSeconds === 'number' && Number.isFinite(durationSeconds)) {
        text += ` (${durationSeconds.toFixed(3)}s)`;
      }

      return {
        level,
        message: text,
        timestamp: Date.now(),
      };
    }
  }

  // NOTE: the message typing are too loose so in practice we should never arrive here.
  return '';
};

import path from 'path';

import fse from 'fs-extra';

import { wrapTransaction } from './common';

import type { Context, MigrationResolver } from './common';

// TODO: check multiple commands in one sql statement
export const migrationResolver: MigrationResolver = ({ name, path: migrationPath, context }) => {
  const { db } = context;

  if (!migrationPath) {
    throw new Error(`Migration ${name} has no path`);
  }

  // if sql file run with knex raw
  if (migrationPath.match(/\.sql$/)) {
    const sql = fse.readFileSync(migrationPath, 'utf8');

    return {
      name,
      path: migrationPath,
      up: wrapTransaction(db)((knex) => knex.raw(sql)),
      async down() {
        throw new Error('Down migration is not supported for sql files');
      },
    };
  }

  // NOTE: we can add some ts register if we want to handle ts migration files at some point
  // eslint-disable-next-line @typescript-eslint/no-var-requires
  const migration = require(migrationPath);
  return {
    name,
    path: migrationPath,
    up: wrapTransaction(db)(migration.up),
    down: wrapTransaction(db)(migration.down),
  };
};

export const resolveMigrationFiles = (filepaths: string[], context: Context) => {
  return filepaths.map((filepath) => {
    const name = path.basename(filepath);
    return migrationResolver({ name, path: filepath, context });
  });
};

import type { MigrationRunnerFn } from './common';
import type { createStorage } from './storage';

export interface MigrationMeta {
  name: string;
  path?: string;
}

export interface RunnableMigration extends MigrationMeta {
  up: MigrationRunnerFn;
  down: MigrationRunnerFn;
}

export interface MigrationRunnerLogger {
  info(message: unknown): void;
}

export interface MigrationRunnerOptions {
  storage: ReturnType<typeof createStorage>;
  logger: MigrationRunnerLogger;
  getMigrations: () => Promise<RunnableMigration[]>;
}

const logEvent = (
  logger: MigrationRunnerLogger,
  event: string,
  name: string,
  extra?: Record<string, unknown>
) => {
  logger.info({ event, name, ...extra });
};

const wrapMigrationError = (name: string, direction: 'up' | 'down', cause: unknown): Error => {
  const causeMessage =
    cause instanceof Error
      ? `Original error: ${cause.message}`
      : `Non-error value thrown. See cause for full value: ${String(cause)}`;

  return new Error(`Migration ${name} (${direction}) failed: ${causeMessage}`, { cause });
};

export const createMigrationRunner = (opts: MigrationRunnerOptions) => {
  const getPendingMigrations = async (): Promise<RunnableMigration[]> => {
    const [migrations, executedNames] = await Promise.all([
      opts.getMigrations(),
      opts.storage.executed(),
    ]);

    const executedSet = new Set(executedNames);
    return migrations.filter((migration) => !executedSet.has(migration.name));
  };

  const getExecutedMigrations = async (): Promise<RunnableMigration[]> => {
    const [migrations, executedNames] = await Promise.all([
      opts.getMigrations(),
      opts.storage.executed(),
    ]);

    const executedSet = new Set(executedNames);
    return migrations.filter((migration) => executedSet.has(migration.name));
  };

  return {
    async pending(): Promise<MigrationMeta[]> {
      const pending = await getPendingMigrations();
      return pending.map(({ name, path }) => ({ name, path }));
    },

    async up(): Promise<MigrationMeta[]> {
      const toBeApplied = await getPendingMigrations();

      for (const migration of toBeApplied) {
        const start = Date.now();

        logEvent(opts.logger, 'migrating', migration.name);

        try {
          await migration.up();
        } catch (error) {
          throw wrapMigrationError(migration.name, 'up', error);
        }

        await opts.storage.logMigration({ name: migration.name });

        const durationSeconds = (Date.now() - start) / 1000;
        logEvent(opts.logger, 'migrated', migration.name, { durationSeconds });
      }

      return toBeApplied.map(({ name, path }) => ({ name, path }));
    },

    async down(): Promise<MigrationMeta[]> {
      const executedReversed = (await getExecutedMigrations()).slice().reverse();
      const toBeReverted = executedReversed.slice(0, 1);

      for (const migration of toBeReverted) {
        const start = Date.now();

        logEvent(opts.logger, 'reverting', migration.name);

        try {
          await migration.down();
        } catch (error) {
          throw wrapMigrationError(migration.name, 'down', error);
        }

        await opts.storage.unlogMigration({ name: migration.name });

        const durationSeconds = Number.parseFloat(((Date.now() - start) / 1000).toFixed(3));
        logEvent(opts.logger, 'reverted', migration.name, { durationSeconds });
      }

      return toBeReverted.map(({ name, path }) => ({ name, path }));
    },
  };
};

import type { Database } from '..';

export interface Options {
  db: Database;
  tableName: string;
}

export const createStorage = (opts: Options) => {
  const { db, tableName } = opts;

  const hasMigrationTable = () => db.getSchemaConnection().hasTable(tableName);

  const createMigrationTable = () => {
    return db.getSchemaConnection().createTable(tableName, (table) => {
      table.increments('id');
      table.string('name');
      table.datetime('time', { useTz: false });
    });
  };

  return {
    async logMigration({ name }: { name: string }) {
      await db
        .getConnection()
        .insert({
          name,
          time: new Date(),
        })
        .into(tableName);
    },

    async unlogMigration({ name }: { name: string }) {
      await db.getConnection(tableName).del().where({ name });
    },

    async executed() {
      if (!(await hasMigrationTable())) {
        await createMigrationTable();
        return [];
      }

      const logs = await db.getConnection(tableName).select().from(tableName).orderBy('time');

      return logs.map((log: { name: string }) => log.name);
    },
  };
};

import path from 'path';

import fse from 'fs-extra';

import { discoverMigrationFiles } from './discover';
import { createMigrationRunner } from './runner';
import { resolveMigrationFiles } from './resolver';
import { createStorage } from './storage';
import { transformLogMessage } from './logger';

import type { UserMigrationProvider } from './common';
import type { Database } from '..';

export const createUserMigrationProvider = (db: Database): UserMigrationProvider => {
  const dir = db.config.settings.migrations.dir;

  fse.ensureDirSync(dir);

  const context = { db };

  const runner = createMigrationRunner({
    storage: createStorage({ db, tableName: 'strapi_migrations' }),
    logger: {
      info(message) {
        db.logger.info(transformLogMessage('info', message));
      },
    },
    async getMigrations() {
      const filepaths = discoverMigrationFiles(path.resolve(dir));
      return resolveMigrationFiles(filepaths, context);
    },
  });

  return {
    async shouldRun() {
      const pendingMigrations = await runner.pending();
      return pendingMigrations.length > 0 && db.config?.settings?.runMigrations === true;
    },
    async up() {
      await runner.up();
    },
    async down() {
      await runner.down();
    },
  };
};

import { difference, keys } from 'lodash/fp';
import { async } from '@strapi/utils';
import { WORKFLOW_MODEL_UID } from '../constants/workflows';
import { getWorkflowContentTypeFilter } from '../utils/review-workflows';

/**
 * Remove CT references from workflows if the CT is deleted
 */
async function migrateDeletedCTInWorkflows({ oldContentTypes, contentTypes }: any) {
  const deletedContentTypes = difference(keys(oldContentTypes), keys(contentTypes)) ?? [];

  if (deletedContentTypes.length) {
    await async.map(deletedContentTypes, async (deletedContentTypeUID: unknown) => {
      const workflow = await strapi.db.query(WORKFLOW_MODEL_UID).findOne({
        select: ['id', 'contentTypes'],
        where: {
          contentTypes: getWorkflowContentTypeFilter({ strapi }, deletedContentTypeUID),
        },
      });

      if (workflow) {
        await strapi.db.query(WORKFLOW_MODEL_UID).update({
          where: { id: workflow.id },
          data: {
            contentTypes: workflow.contentTypes.filter(
              (contentTypeUID: unknown) => contentTypeUID !== deletedContentTypeUID
            ),
          },
        });
      }
    });
  }
}

export default migrateDeletedCTInWorkflows;

import { get, keys, pickBy, pipe } from 'lodash/fp';
import { WORKFLOW_MODEL_UID } from '../constants/workflows';

async function migrateWorkflowsContentTypes({ oldContentTypes, contentTypes }: any) {
  // Look for RW contentTypes attribute
  const hadContentTypes = !!oldContentTypes?.[WORKFLOW_MODEL_UID]?.attributes?.contentTypes;
  const hasContentTypes = !!contentTypes?.[WORKFLOW_MODEL_UID]?.attributes?.contentTypes;

  if (!hadContentTypes && hasContentTypes) {
    // Initialize contentTypes with an empty array and assign only to one
    // workflow the Content Types which were using Review Workflow before.
    await strapi.db.query(WORKFLOW_MODEL_UID).updateMany({ data: { contentTypes: [] } });

    // Find Content Types which were using Review Workflow before
    const contentTypes = pipe([pickBy(get('options.reviewWorkflows')), keys])(oldContentTypes);

    if (contentTypes.length) {
      // Update only one workflow with the contentTypes
      // Before this release there was only one workflow, so this operation is safe.
      await strapi.db
        .query(WORKFLOW_MODEL_UID)
        .update({ where: { id: { $notNull: true } }, data: { contentTypes } });
    }
  }
}

export default migrateWorkflowsContentTypes;

import { STAGE_DEFAULT_COLOR, STAGE_MODEL_UID } from '../constants/workflows';

/**
 * Set the default color for stages if the color attribute was added
 */
async function migrateReviewWorkflowStagesColor({ oldContentTypes, contentTypes }: any) {
  // Look for CT's color attribute
  const hadColor = !!oldContentTypes?.[STAGE_MODEL_UID]?.attributes?.color;
  const hasColor = !!contentTypes?.[STAGE_MODEL_UID]?.attributes?.color;

  // Add the default stage color if color attribute was added
  if (!hadColor && hasColor) {
    await strapi.db.query(STAGE_MODEL_UID).updateMany({
      data: {
        color: STAGE_DEFAULT_COLOR,
      },
    });
  }
}

export default migrateReviewWorkflowStagesColor;
